import React, { useState } from 'react';
import ResetPasswordModal from './ResetPasswordModal';

export default function StudentDashboard({ userName, handleLogout }) {
  const [showResetModal, setShowResetModal] = useState(false);
  const [activeTab, setActiveTab] = useState('dashboard');
  
  // මේවා Database එකෙන් ගන්න පුළුවන්, දැනට ලස්සනට පේන්න මම දාලා තියෙන්නේ
  const summary = { enrolled: 1, subjects: 4, materials: 12, quizzes: 2 };

  return (
    <div style={{ display: 'flex', minHeight: '100vh', backgroundColor: '#f4f7f6', fontFamily: 'sans-serif' }}>
      
      {/* 🟢 වම් පැත්තේ මෙනුව (Sidebar) */}
      <div style={{ width: '250px', backgroundColor: '#15803d', color: 'white', padding: '20px 0', display: 'flex', flexDirection: 'column' }}>
        <div style={{ padding: '0 20px', marginBottom: '30px', textAlign: 'center' }}>
          <h2 style={{ margin: 0, fontSize: '22px', borderBottom: '1px solid rgba(255,255,255,0.2)', paddingBottom: '10px' }}>STUDENT PORTAL</h2>
        </div>
        
        <div style={{ display: 'flex', flexDirection: 'column', gap: '5px' }}>
          <SidebarBtn active={activeTab === 'dashboard'} onClick={() => setActiveTab('dashboard')} icon="🏠" text="Dashboard" />
          <SidebarBtn active={activeTab === 'subjects'} onClick={() => setActiveTab('subjects')} icon="📚" text="My Subjects" />
          <SidebarBtn active={activeTab === 'quizzes'} onClick={() => setActiveTab('quizzes')} icon="📝" text="Online Quizzes" />
          <SidebarBtn active={activeTab === 'profile'} onClick={() => setShowResetModal(true)} icon="⚙️" text="Settings / Password" />
        </div>

        <div style={{ marginTop: 'auto', padding: '20px' }}>
          <button onClick={handleLogout} style={{ width: '100%', padding: '12px', backgroundColor: '#ef4444', color: 'white', border: 'none', borderRadius: '8px', cursor: 'pointer', fontWeight: 'bold' }}>
            🚪 Logout
          </button>
        </div>
      </div>

      {/* 🟢 දකුණු පැත්තේ ප්‍රධාන කොටස */}
      <div style={{ flex: 1, padding: '40px', overflowY: 'auto' }}>
        <div style={{ backgroundColor: 'white', padding: '25px', borderRadius: '12px', boxShadow: '0 4px 15px rgba(0,0,0,0.05)', marginBottom: '30px' }}>
          <h1 style={{ margin: '0 0 5px 0', color: '#1e293b', fontSize: '28px' }}>Welcome, {userName}</h1>
          <p style={{ margin: 0, color: '#64748b' }}>Access your courses, quizzes, learning materials, and academic activities.</p>
        </div>

        {/* 🟢 Summary Cards (අර යාලුවගේ තිබ්බ ලස්සන කොටු ටික) */}
        <div style={{ display: 'grid', gridTemplateColumns: 'repeat(auto-fit, minmax(200px, 1fr))', gap: '20px', marginBottom: '40px' }}>
          <DashboardCard title="Enrolled Courses" count={summary.enrolled} color="#3b82f6" />
          <DashboardCard title="Total Subjects" count={summary.subjects} color="#10b981" />
          <DashboardCard title="Learning Materials" count={summary.materials} color="#f59e0b" />
          <DashboardCard title="Total Quizzes" count={summary.quizzes} color="#8b5cf6" />
        </div>

        {/* 🟢 Subjects Area */}
        <div style={{ backgroundColor: 'white', padding: '25px', borderRadius: '12px', boxShadow: '0 4px 15px rgba(0,0,0,0.05)' }}>
          <h3 style={{ borderBottom: '2px solid #e2e8f0', paddingBottom: '10px', color: '#334155', marginTop: 0 }}>My Academic Courses</h3>
          
          <div style={{ padding: '15px', backgroundColor: '#f8fafc', borderLeft: '4px solid #15803d', borderRadius: '8px', marginTop: '15px' }}>
             <h4 style={{ margin: '0 0 5px 0', color: '#1e293b', fontSize: '18px' }}>O/L Science & Mathematics</h4>
             <p style={{ margin: '0 0 10px 0', color: '#64748b', fontSize: '14px' }}>Science, Mathematics, IT, English</p>
             <button style={{ padding: '8px 15px', backgroundColor: '#e2e8f0', border: 'none', borderRadius: '6px', cursor: 'pointer', fontWeight: 'bold', color: '#334155' }}>View Materials</button>
          </div>
        </div>
      </div>

      {showResetModal && <ResetPasswordModal userName={userName} role="student" setShowResetModal={setShowResetModal} />}
    </div>
  );
}

// Cards සහ Buttons වලට අදාළ පොඩි Components 
const SidebarBtn = ({ active, onClick, icon, text }) => (
  <button onClick={onClick} style={{ width: '100%', textAlign: 'left', padding: '15px 25px', backgroundColor: active ? 'rgba(255,255,255,0.1)' : 'transparent', color: 'white', border: 'none', borderLeft: active ? '4px solid #facc15' : '4px solid transparent', cursor: 'pointer', fontSize: '16px', display: 'flex', alignItems: 'center', gap: '10px', transition: '0.3s' }}>
    <span>{icon}</span> {text}
  </button>
);

const DashboardCard = ({ title, count, color }) => (
  <div style={{ backgroundColor: 'white', padding: '20px', borderRadius: '12px', boxShadow: '0 4px 15px rgba(0,0,0,0.05)', borderBottom: `4px solid ${color}` }}>
    <p style={{ margin: '0 0 10px 0', color: '#64748b', fontSize: '14px', fontWeight: 'bold' }}>{title}</p>
    <h2 style={{ margin: 0, color: '#1e293b', fontSize: '36px' }}>{count}</h2>
  </div>
);
